// Lit la réponse Gemini et rend l’enveloppe exactement ce qu'attend le service
// `/assistant` (`askN8n` / `extractN8nReply`, src/lib/assistant.js) :
// { ok, reply, provider, model }. Les suggestions et l’ancrage dans les données
// réelles restent produits par la Function, qui seule a la clé serveur Appwrite
// — n8n ne voit jamais la base.
//
// Une réponse vide ou filtrée lève : le nœud « Répondre » renvoie alors une
// erreur, la Function la compte comme un échec de la passerelle et bascule sur
// Mistral. C'est le comportement voulu, pas une panne.
//
// provider reste « gemini » et le modèle reste verrouillé ici, en dur : les
// trois clients affichent déjà ce libellé (UniAssistant.tsx côté web,
// uni_assistant.dart côté mobile et desktop), donc aucun code client ne bouge.
// Le modèle n'est PAS lu depuis la requête — l'invariant du 2026-09-21 est
// conservé, il a juste changé de place : la main sur le coût du modèle est
// désormais dans l’éditeur n8n, et donc à toute personne ayant accès à cette
// console.

const payload = $input.first().json || {}
const parts = payload?.candidates?.[0]?.content?.parts
const text = (Array.isArray(parts) ? parts : []).map((p) => (typeof p?.text === 'string' ? p.text : '')).join('').trim()

if (!text) {
  const motif = payload?.promptFeedback?.blockReason || payload?.candidates?.[0]?.finishReason || 'ABSENT'
  throw new Error(`GEMINI_EMPTY ${motif}`)
}

// Le reply part en TEXTE BRUT, jamais en HTML : le chat web rend le message
// échappé et les bulles Flutter sont des widgets Text() — un étudiant lirait les
// balises. Le HTML est réservé aux canaux que n8n possède (Gmail, Telegram, PDF).
return [{ json: { ok: true, reply: text, provider: 'gemini', model: 'gemini-3.1-flash-lite', assistant: 'Uni' } }]
